notes=json.loads((ROOT/'scripts/book-context-complete/1-thessalonians.json').read_text(encoding='utf8'));sources=[]
s=source('web','First Thessalonians · World English Bible','https://ebible.org/engwebp/1TH01.htm','All five chapters supply the primary text for original close readings.','Scripture','historical','Dates, original manuscripts, Greek forms, the blocked visits\x27 exact cause, and a complete harmony with Acts were not independently verified. The accusations in chapter two remain part of the letter\x27s conflict rather than independent evidence against all Jewish people. No return date is assigned.')
